#include "tinymt32.h"
#include <stdio.h>

#define MIN_LOOP 8
#define PRE_LOOP 8

/**
* This function represents a function used in the initialization
* by init_by_array
* @param x 32-bit integer
* @return 32-bit integer
*/
static uint32_t ini_func1(uint32_t x) {
	return (x ^ (x >> 27)) * (uint32_t)1664525UL;
}

/**
* This function represents a function used in the initialization
* by init_by_array
* @param x 32-bit integer
* @return 32-bit integer
*/
static uint32_t ini_func2(uint32_t x) {
	return (x ^ (x >> 27)) * (uint32_t)1566083941UL;
}

/**
* This function certificate the period of 2^127-1.
* @param random tinymt state vector.
*/
static void period_certification(tinymt32_t *random) {
	if ((random->status[0] & TINYMT32_MASK) == 0 &&
		random->status[1] == 0 &&
		random->status[2] == 0 &&
		random->status[3] == 0) {
		random->status[0] = 'T';
		random->status[1] = 'I';
		random->status[2] = 'N';
		random->status[3] = 'Y';
	}
}


/**
 * This function changes internal state of tinymt32.
 * Users should not call this function directly.
 * @param random tinymt internal status
 */
inline static void tinymt32_next_state(tinymt32_t * random) {
	uint32_t x;
	uint32_t y;

	y = random->status[3];
	x = (random->status[0] & TINYMT32_MASK)
		^ random->status[1]
		^ random->status[2];
	x ^= (x << TINYMT32_SH0);
	y ^= (y >> TINYMT32_SH0) ^ x;
	random->status[0] = random->status[1];
	random->status[1] = random->status[2];
	random->status[2] = x ^ (y << TINYMT32_SH1);
	random->status[3] = y;
	int32_t const a = -((int32_t)(y & 1)) & (int32_t)random->mat1;
	int32_t const b = -((int32_t)(y & 1)) & (int32_t)random->mat2;
	random->status[1] ^= (uint32_t)a;
	random->status[2] ^= (uint32_t)b;
}

/**
 * This function outputs 32-bit unsigned integer from internal state.
 * Users should not call this function directly.
 * @param random tinymt internal status
 * @return 32-bit unsigned pseudorandom number
 */
inline static uint32_t tinymt32_temper(tinymt32_t * random) {
	uint32_t t0, t1;
	t0 = random->status[3];
	t1 = random->status[0]
		+ (random->status[2] >> TINYMT32_SH8);
	t0 ^= t1;

	if ((t1 & 1)) {
		t0 ^= random->tmat;
	}
	return t0;
}


/**
* This function initializes the internal state array with a 32-bit
* unsigned integer seed.
* @param random tinymt state vector.
* @param seed a 32-bit unsigned integer used as a seed.
*/
void tinymt32_init(tinymt32_t *random, uint32_t seed) {
	random->status[0] = seed;
	random->status[1] = random->mat1;
	random->status[2] = random->mat2;
	random->status[3] = random->tmat;

	for (int i = 1; i < MIN_LOOP; i++) {
		random->status[i & 3] ^= i + UINT32_C(1812433253)
			* (random->status[(i - 1) & 3]
				^ (random->status[(i - 1) & 3] >> 30));
	}
	period_certification(random);
	for (int i = 0; i < PRE_LOOP; i++) {
		tinymt32_next_state(random);
	}
}


/**
* This function generates and returns 32-bit unsigned integer.
* @param random tinymt state vector.
* @return 32-bit unsigned integer r (0 <= r < 2^32)
*/
uint32_t tinymt32_generate_uint32(tinymt32_t *random) {
	tinymt32_next_state(random);
	return tinymt32_temper(random);
}

/**
* This function generates and returns double precision pseudorandom number.
* @param random tinymt state vector.
* @return double precision floating point pseudorandom number
*/
double tinymt32_generate_double(tinymt32_t *random) {
	uint32_t x = tinymt32_generate_uint32(random) >> 5;
	uint32_t y = tinymt32_generate_uint32(random) >> 6;
	return ((x * 67108864.0) + y) * (1.0/9007199254740992.0);
}
